package com.ridex.location.config;
import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import jakarta.servlet.FilterChain; import jakarta.servlet.http.*; import org.junit.jupiter.api.*; import org.springframework.mock.web.*; import org.springframework.security.core.context.SecurityContextHolder; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class JwtAuthenticationFilterTest { static final String SECRET="a-very-long-test-secret-key-for-ridex-location-service"; SecretKey key=Keys.hmacShaKeyFor(SECRET.getBytes(StandardCharsets.UTF_8)); JwtAuthenticationFilter filter; FilterChain chain; @BeforeEach void setup(){filter=new JwtAuthenticationFilter(SECRET);chain=mock(FilterChain.class);SecurityContextHolder.clearContext();} @AfterEach void clear(){SecurityContextHolder.clearContext();} String token(UUID id,String role){return Jwts.builder().subject(id.toString()).claim("role",role).signWith(key).compact();} @Test void validTokenAuthenticatesPrincipal() throws Exception {UUID id=UUID.randomUUID();MockHttpServletRequest req=new MockHttpServletRequest();req.addHeader("Authorization","Bearer "+token(id,"DRIVER"));filter.doFilter(req,new MockHttpServletResponse(),chain);assertNotNull(SecurityContextHolder.getContext().getAuthentication());assertEquals("ROLE_DRIVER",SecurityContextHolder.getContext().getAuthentication().getAuthorities().iterator().next().getAuthority());verify(chain).doFilter(any(),any());} @Test void missingHeaderContinuesUnauthenticated() throws Exception {filter.doFilter(new MockHttpServletRequest(),new MockHttpServletResponse(),chain);assertNull(SecurityContextHolder.getContext().getAuthentication());verify(chain).doFilter(any(),any());} @Test void invalidTokenContinuesUnauthenticated() throws Exception {MockHttpServletRequest req=new MockHttpServletRequest();req.addHeader("Authorization","Bearer invalid");filter.doFilter(req,new MockHttpServletResponse(),chain);assertNull(SecurityContextHolder.getContext().getAuthentication());verify(chain).doFilter(any(),any());} @Test void nonBearerHeaderIsIgnored() throws Exception {MockHttpServletRequest req=new MockHttpServletRequest();req.addHeader("Authorization","Basic abc");filter.doFilter(req,new MockHttpServletResponse(),chain);assertNull(SecurityContextHolder.getContext().getAuthentication());} }
